WITH valid AS (SELECT *, CASE WHEN device IN ('desktop', 'tablet') THEN 'Tier 1' ELSE 'Other' END device_group, COALESCE(browser, 'DIRECT') browser_filled FROM sessions WHERE started_at >= TO_DATE('2023-03-24') AND customer_id IN (27, 34, 35, 40)) SELECT s.*, latest.web_event_page, latest.web_event_duration_sec FROM valid s LEFT JOIN LATERAL (SELECT c.page AS web_event_page, c.duration_sec AS web_event_duration_sec FROM web_events c WHERE c.session_id = s.id ORDER BY c.event_time DESC, c.id DESC LIMIT 1) latest ON TRUE
